    {
      "question": "Where is price realisation lowest \u2014 which branches or categories are giving the biggest discounts?",
      "sql": "SELECT `Branch`, `Category`, MEASURE(`Price Realisation Pct`) FROM vmohan_demo_catalog.cfo_workbench.mv_revenue_margin WHERE `Week Start` = '2026-11-09' GROUP BY ALL",
